Usage:
    from openai_client import send_prompt

    response = send_prompt(\"What is the capital of France?\")
    print(response.output_text)

Environment:
    OPENAI_API_KEY  Your OpenAI API key (required).
\"\"\"

from __future__ import annotations

import json
import os
import ssl
import sys
from typing import Any
from urllib.error import URLError
from urllib.request import Request, urlopen


DEFAULT_MODEL = \"gpt-4o\"
BASE_URL = \"https://api.openai.com/v1/responses\"


class OpenAIError(Exception):
    \"\"\"Raised when the API returns an error or a network failure occurs.\"\"\"


class _Response:
    \"\"\"Thin wrapper around a Responses API response dict.\"\"\"

    def __init__(self, raw: dict[str, Any]) -> None:
        self._raw = raw

    @property
    def id(self) -> str:
        return self._raw.get(\"id\", \"\")

    @property
    def model(self) -> str:
        return self._raw.get(\"model\", \"\")

    @property
    def output_text(self) -> str:
        \"\"\"Convenience: return the concatenated text of all output messages.

        The Responses API returns "'``output`` as a list of items.  This
        property extracts the ``text`` field from each message item and
        joins them with newlines.
        """
        parts: list[str] = []
        for item in self._raw.get("output", []):
            if item.get("type") == "message":
                for content in item.get("content", []):
                    if content.get("type") == "output_text":
                        parts.append(content.get("text", ""))
        return "'"\\n\".join(parts)

    def __repr__(self) -> str:
        return f\"<_Response id={self.id"'!r} model={self.model!r}>"


def _get_api_key() -> str:
    key = os.environ.get("OPENAI_API_KEY")
    if not key:
        raise OpenAIError(
            "OPENAI_API_KEY environment variable is not set"
        )
    return key


def send_prompt(
    prompt: str,
    *,
    model: str = DEFAULT_MODEL,
    instructions: str | None = None,
    temperature: float | None = None,
    max_output_tokens: int | None = None,
    **extra_kwargs: Any,
) -> _Response:
    """Send a text prompt to the OpenAI Responses API and return the response.

    Parameters
    ----------
    prompt:
        The user message to send.
    model:
        Model identifier (e.g. ``"gpt-4o"``, ``"gpt-4o-mini"``).
    instructions:
        Optional system-level instructions (analogous to the system prompt).
    temperature:
        Sampling temperature (0-2).  ``None`` uses the API default.
    max_output_tokens:
        Maximum tokens the model may generate.
    **extra_kwargs:
        Any other top-level key accepted by the Responses API
        (e.g. ``store=False``, ``metadata=...``).

    Returns
    -------
    _Response
        Wrapped API response with convenient property access.

    Raises
    ------
    OpenAIError
        On network errors, non-2xx HTTP status, or a missing API key.
    """
    api_key = [REDACTED_SECRET]

    body: dict[str, Any] = {
        "model": model,
        "input": prompt,
    }
    if instructions is not None:
        body["instructions"] = instructions
    if temperature is not None:
        body["temperature"] = temperature
    if max_output_tokens is not None:
        body["max_output_tokens"] = max_output_tokens
    body.update(extra_kwargs)

    data = json.dumps(body).encode("utf-8")
    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
    }

    req = Request(BASE_URL, data=data, headers=headers, method="POST")
    try:
        with urlopen(req, context=ssl.create_default_context()) as resp:
            raw: dict[str, Any] = json.loads(resp.read().decode("utf-8"))
    except URLError as exc:
        raise OpenAIError(f"API request failed: {exc}") from exc
    except json.JSONDecodeError as exc:
        raise OpenAIError(f"Invalid JSON in API response: {exc}") from exc
    except OSError as exc:
        raise OpenAIError(f"Network error: {exc}") from exc

    if "error" in raw:
        err = raw["error"]
        raise OpenAIError(
            f"API error: {err.get('"'type', 'unknown')}: \"
            f\"{err.get('message', '')}\"
        )

    return _Response(raw)


def __getattr__(name: str) -> Any:
    \"\"\"Provide a friendly "'``__version__`` without cluttering the namespace."""
    if name == "__version__":
        return "0.1.0"
    raise AttributeError(f"module {__name__!r} has no attribute {name!r}")


if __name__ == "__main__":
    # Simple CLI wrapper: prompt is read from argv or stdin.
    if len(sys.argv) > 1:
        prompt = " ".join(sys.argv[1:])
    elif not sys.stdin.isatty():
        prompt = sys.stdin.read()
    else:
        print("Usage: python openai_client.py <prompt>", file=sys.stderr)
        sys.exit(1)

    try:
        resp = send_prompt(prompt.strip())
    except OpenAIError as exc:
        print(f"Error: {exc}", file=sys.stderr)
        sys.exit(1)

    print(resp.output_text)
PYEOF'

